/**
 * Fuzz of `content.ts#tokenizeContent`, called directly. Lot 1 of the PDF fuzz design (16/11/2026).
 * Two kinds of input. Real page content streams of fixtures, decoded by the reader, then widened, commented, rewritten
 * or damaged. And operator lists generated by fast-check, spelled by a test writer made from ISO 32000-1:2008 (§7.2
 * lexical conventions, §7.3 objects, §7.8.2 content streams, §8.9.7 inline images: `pdf-syntax-writer.test.support.ts`).
 * Properties: a white space widened or a comment inserted outside a string changes nothing (§7.2.2, §7.2.3); writing
 * then reading gives the same operators; the node count is the one the model predicts; damaged bytes give a result or
 * a refusal of ours, never a raw error; the work stays linear (operators and nodes at most 2 per byte, see below).
 *
 * The seed is fixed (`PDF_FUZZ_SEED`): a red run replays as is. The run counts are the written ones, times the weekly
 * multiplier (`lib/pdf-fuzz-runs.test.support.ts`).
 * NOT covered: what the operators mean, inline images of real files (none of the seeds has one).
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import fc from "fast-check";
import { describe, expect, it, vi } from "vitest";

import { tokenizeContent, type ContentOp } from "./content";
import { openPdfObjects } from "./document";
import {
  Choices,
  contentNodes,
  drawsArb,
  expectedOps,
  modelOf,
  opsArb,
  type OpModel,
  writeContent,
} from "./pdf-syntax-writer.test.support";
import { PdfObjectsRefusal } from "./refusal";
import { PDF_FUZZ_SEED } from "../pdf-fuzz-outcome.test.support";
import { fuzzRuns, fuzzTestTimeout } from "../../lib/pdf-fuzz-runs.test.support";

vi.setConfig({ testTimeout: fuzzTestTimeout(20000, process.env) });

const params = (baseRuns: number): fc.Parameters<unknown> => ({
  numRuns: fuzzRuns(baseRuns, process.env),
  seed: PDF_FUZZ_SEED,
  timeout: 8000,
});

const here = dirname(fileURLToPath(import.meta.url));

/** The decoded content streams of the first page of a fixture. English first (the corpus rule), then French. */
function pageStreams(file: string): Uint8Array[] {
  const doc = openPdfObjects(new Uint8Array(readFileSync(join(here, "../../../fixtures/pdf", file))));
  const page = doc.pages()[0];
  const contents = doc.resolve(page?.dict.get("Contents"));
  const list = contents?.kind === "array" ? contents.items.map((item) => doc.resolve(item)) : [contents];
  return list.flatMap((stream) => (stream?.kind === "stream" ? [doc.streamBytes(stream)] : []));
}

const SEEDS: readonly Uint8Array[] = [
  "38-SOP-Video-Appraisals-Word365.pdf",
  "55-PA-Annual-Report-2022-Word.pdf",
  "05a-Rapport-Annuel-Digital.pdf",
  "47-GrandSoissons-Deliberations-2022-PDFium.pdf",
].flatMap(pageStreams);

/** A seed by its index: a counter-example prints the index, not the kilobytes of the stream. */
const seedArb = fc.integer({ min: 0, max: SEEDS.length - 1 });
const seedAt = (index: number): Uint8Array => SEEDS[index] as Uint8Array;

/** §7.2.2 Table 1. */
const WHITE = [0x00, 0x09, 0x0a, 0x0c, 0x0d, 0x20];

/** Past a literal string at `from` (its `(`): balanced parentheses, a backslash escapes the next byte (§7.3.4.2). */
function pastLiteral(data: Uint8Array, from: number): number {
  let depth = 0;
  let at = from;
  while (at < data.length) {
    const byte = data[at] as number;
    if (byte === 0x5c) at += 1;
    else if (byte === 0x28) depth += 1;
    else if (byte === 0x29 && --depth === 0) return at + 1;
    at += 1;
  }
  return at;
}

/** Past the token or comment at `from` that may hold white space of its own: a literal string, a hex string
 *  (§7.3.4.3), a comment (§7.2.3). `from` itself when there is none. */
function pastOpaque(data: Uint8Array, from: number): number {
  const byte = data[from];
  if (byte === 0x28) return pastLiteral(data, from);
  if (byte === 0x3c && data[from + 1] === 0x3c) return from + 2;
  if (byte === 0x3c) {
    const close = data.indexOf(0x3e, from);
    return close < 0 ? data.length : close + 1;
  }
  if (byte === 0x25) {
    let at = from;
    while (at < data.length && data[at] !== 0x0a && data[at] !== 0x0d) at += 1;
    return at;
  }
  return from;
}

/** The white-space bytes that separate tokens: outside strings and comments. A naive scan written from §7.2, not the
 *  reader's; valid for a stream without an inline image, which the test checks first. */
function separatorPositions(data: Uint8Array): number[] {
  const positions: number[] = [];
  let at = 0;
  while (at < data.length) {
    const past = pastOpaque(data, at);
    if (past !== at) {
      at = past;
      continue;
    }
    if (WHITE.includes(data[at] as number)) positions.push(at);
    at += 1;
  }
  return positions;
}

const insertAt = (data: Uint8Array, at: number, extra: Uint8Array): Uint8Array => {
  const out = new Uint8Array(data.length + extra.length);
  out.set(data.subarray(0, at));
  out.set(extra, at);
  out.set(data.subarray(at), at + extra.length);
  return out;
};

const latin1 = (text: string): Uint8Array => Uint8Array.from(text, (char) => char.charCodeAt(0));

/** A run of 1 to 4 white-space bytes, or a comment of any bytes but an end of line, then its end of line. */
const fillerArb = fc.oneof(
  fc.array(fc.constantFrom(...WHITE), { minLength: 1, maxLength: 4 }).map((codes) => Uint8Array.from(codes)),
  fc
    .tuple(
      fc.array(
        fc.integer({ min: 0, max: 255 }).filter((code) => code !== 0x0a && code !== 0x0d),
        { maxLength: 12 },
      ),
      fc.constantFrom("\n", "\r", "\r\n"),
    )
    .map(([body, eol]) => Uint8Array.from([0x25, ...body, ...latin1(eol)])),
);

/** The operators of a stream read by the reader, written back with the test writer. */
function rewritten(ops: readonly ContentOp[], choices: Choices): Uint8Array {
  const models: OpModel[] = ops.map((op) => ({ kind: "op", op: op.op, operands: op.operands.map(modelOf) }));
  return writeContent(models, choices).bytes;
}

/** Fragments that open, close or end a token or a container (the design's « dictionary »). */
const FRAGMENTS = ["(", ")", "<", ">", "<<", ">>", "[", "]", "{", "}", "/", "%", "\\", "#", "\r", "\n", "\0", " "]
  .concat(["BI", "ID", "EI", "BT", "ET", "Tj", "TJ", "true", "null", "1e5", "--1", ".", "/#00", "<zz>"])
  .map(latin1);

type Damage =
  | { readonly kind: "overwrite"; readonly at: number; readonly bytes: Uint8Array }
  | { readonly kind: "insert"; readonly at: number; readonly bytes: Uint8Array }
  | { readonly kind: "cut"; readonly at: number; readonly length: number };

const damageArb: fc.Arbitrary<Damage> = fc.oneof(
  fc.record({
    kind: fc.constant("overwrite" as const),
    at: fc.nat(),
    bytes: fc.uint8Array({ minLength: 1, maxLength: 8 }),
  }),
  fc.record({ kind: fc.constant("insert" as const), at: fc.nat(), bytes: fc.constantFrom(...FRAGMENTS) }),
  fc.record({ kind: fc.constant("cut" as const), at: fc.nat(), length: fc.integer({ min: 1, max: 4096 }) }),
);

function damaged(data: Uint8Array, damage: Damage): Uint8Array {
  const at = damage.at % (data.length + 1);
  if (damage.kind === "insert") return insertAt(data, at, damage.bytes);
  if (damage.kind === "cut") {
    const out = new Uint8Array(data.length - Math.min(damage.length, data.length - at));
    out.set(data.subarray(0, at));
    out.set(data.subarray(at + damage.length), at);
    return out;
  }
  // A copy, never a view: `streamBytes` may hand a Buffer, whose `slice` shares the seed's bytes across trials.
  const out = Uint8Array.from(data);
  damage.bytes.forEach((byte, index) => {
    if (at + index < out.length) out[at + index] = byte;
  });
  return out;
}

/** Starting value to calibrate, from the reader's own definition of a node: every turn of the tokenizer's loop
 *  consumes at least one byte, and so does every node an operand holds; an operator is at least one byte. */
const WORK_PER_BYTE = 2;

/** The tokenizer's result, or `undefined` when it refuses; any other error fails the property. */
function tokenizeOrRefuse(data: Uint8Array): ReturnType<typeof tokenizeContent> | undefined {
  try {
    return tokenizeContent(data);
  } catch (error) {
    expect(error, "a refusal of ours, never a raw error").toBeInstanceOf(PdfObjectsRefusal);
    return undefined;
  }
}

describe("tokenizeContent - real page streams", () => {
  it("the seeds read, without an inline image (the separator scan relies on it)", () => {
    expect(SEEDS.length).toBeGreaterThanOrEqual(4);
    for (const seed of SEEDS) expect(tokenizeContent(seed).ops.some((op) => op.op === "BI")).toBe(false);
  });

  it("a white space widened or a comment inserted outside a string changes nothing (7.2.2, 7.2.3)", () => {
    fc.assert(
      fc.property(seedArb, fc.nat(), fillerArb, (index, pick, filler) => {
        const seed = seedAt(index);
        const positions = separatorPositions(seed);
        const at = (positions[pick % positions.length] as number) + 1;
        const before = tokenizeContent(seed);
        const after = tokenizeContent(insertAt(seed, at, filler));
        expect(after.ops).toEqual(before.ops);
        expect(after.nodes).toBe(before.nodes);
      }),
      params(60),
    );
  });

  it("the operators read, written back with other spellings, read the same", () => {
    fc.assert(
      fc.property(seedArb, drawsArb, (index, draws) => {
        const { ops } = tokenizeContent(seedAt(index));
        expect(tokenizeContent(rewritten(ops, new Choices(draws))).ops).toEqual(ops);
      }),
      params(20),
    );
  });

  it("damaged bytes give operators or a refusal of ours, with a bounded work, the same way twice", () => {
    let read = 0;
    let trials = 0;
    fc.assert(
      fc.property(seedArb, fc.array(damageArb, { minLength: 1, maxLength: 3 }), (index, damages) => {
        const bytes = damages.reduce(damaged, seedAt(index));
        const result = tokenizeOrRefuse(bytes);
        trials += 1;
        if (result === undefined) return;
        read += 1;
        expect(result.ops.length, "operators per byte").toBeLessThanOrEqual(bytes.length);
        expect(result.nodes, "nodes per byte").toBeLessThanOrEqual(WORK_PER_BYTE * bytes.length);
        expect(tokenizeContent(bytes)).toEqual(result);
      }),
      params(100),
    );
    // Starting value to calibrate: the damage must not refuse every trial, or the property sees nothing past the
    // first refusal. Measured on 24/11/2026 with this seed: 7 read in 100, 112 in 1 000. Most damage lands in a `TJ`
    // array, and an array left open takes the operators after it as values: `syntax`, for most refusals.
    expect(read / trials, "share of damaged streams that read").toBeGreaterThanOrEqual(0.04);
  });
});

describe("tokenizeContent - generated operator lists", () => {
  it("writing then reading gives the same operators (7.8.2, 8.9.7)", () => {
    fc.assert(
      fc.property(opsArb, drawsArb, (ops, draws) => {
        const { bytes } = writeContent(ops, new Choices(draws));
        expect(tokenizeContent(bytes).ops).toEqual(expectedOps(ops));
      }),
      params(200),
    );
  });

  it("the node count is the one the model predicts, and stays within the work bound", () => {
    fc.assert(
      fc.property(opsArb, drawsArb, (ops, draws) => {
        const { bytes, trailingBlank } = writeContent(ops, new Choices(draws));
        const { nodes } = tokenizeContent(bytes);
        expect(nodes).toBe(contentNodes(ops, trailingBlank));
        expect(nodes, "nodes per byte").toBeLessThanOrEqual(WORK_PER_BYTE * bytes.length);
      }),
      params(200),
    );
  });
});
